mapper.update:
UPDATE lunaerp_production_dyeing_color
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE dyeing_order_id = #{dyeingOrderId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_production_dyeing_color
WHERE dyeing_order_id = #{dyeingOrderId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
